<script setup lang="ts">import{onMounted,ref}from'vue';import{Building2,MapPin,Store}from'@lucide/vue';import{api,errorMessage}from'../lib/api';const companies=ref<any[]>([]),error=ref('');onMounted(async()=>{try{companies.value=(await api.get('/network')).data.data}catch(e){error.value=errorMessage(e)}})</script>
<template><div class="page-heading"><div><p class="eyebrow">TRUSTED NETWORK</p><h1>Companies</h1><p>Discover marketplace-visible organizations in the ReStockr network.</p></div></div><div v-if="error" class="form-error">{{error}}</div><div class="offer-grid"><article v-for="c in companies" :key="c.id" class="offer-card"><div class="kpi-icon blue"><Building2/></div><h3>{{c.name}}</h3><p class="muted">{{c.type}}</p><div class="offer-meta"><span><MapPin :size="16"/>{{c.country}}</span><span><Store :size="16"/>{{c.activeListings}} listings</span></div><p>{{c.locations}} active locations</p><RouterLink class="primary wide" to="/marketplace">Browse offers</RouterLink></article></div><div v-if="!companies.length&&!error" class="panel empty"><Building2/><strong>No public companies found</strong></div></template>
